};
logging {
channel default_debug {
file "data/named.run";
severity dynamic;
};
};
zone "." IN {
type hint;
file "named.ca";
};
zone "homelab.jhw" IN {
type master;
file "forward.homelab.jhw";
allow-update { none; };
allow-query { any; };
};
zone "1.168.192.in-addr.arpa" IN {
type master;
file "reverse.homelab.jhw";
allow-update { none; };
allow-query { any; };
};
zone "16.172.in-addr.arpa" IN {
type master;
file "reverse2.homelab.jhw";
allow-update { none; };
allow-query { any; };
};
include "/etc/named.rfc1912.zones";
include "/etc/named.root.key";
